function(container, apiUrl, tables) {
  // テーブルインデックスの定義
  const STORE_TABLE = 1; // 店舗マスタ
  const PRODUCT_TABLE = 2; // 商品マスタ
  const ORDER_TABLE = 7; // 発注データ

  let currentOrders = [];
  let stores = [];
  let products = [];

  // 現在の日付を設定
  const today = new Date();
  const orderDateInput = container.querySelector('#order-date');
  orderDateInput.value = today.toLocaleDateString('ja-JP');

  // 発注データ再描画関数
  function renderOrderRows(orders) {
    const tbody = container.querySelector('#order-list-tbody');

    if (!orders || orders.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" style="text-align: center; color: var(--text-muted);">発注対象のデータがありません</td></tr>';
      updateTotalAmount();
      return;
    }

    tbody.innerHTML = orders.map(order => {
      const product = products.find(p => p.id === order.商品ID) || {};
      const statusClass = getStatusClass(order.発注ステータス);
      const isDisabled = order.発注ステータス === '送信済み' ? 'disabled' : '';

      return `
        <tr data-id="${order.id}">
          <td>
            <input type="checkbox" class="individual-checkbox" data-id="${order.id}" ${isDisabled}>
          </td>
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td>${order.予測数量 || 0}</td>
          <td>${order.発注数量 || 0}</td>
          <td>${order.仕入先名 || ''}</td>
          <td>¥${(order.発注金額 || 0).toLocaleString()}</td>
          <td><span class="${statusClass}">${order.発注ステータス || '送信待ち'}</span></td>
        </tr>
      `;
    }).join('');

    updateTotalAmount();
  }

  // ステータスのCSSクラスを取得
  function getStatusClass(status) {
    switch(status) {
      case '送信済み': return 'status-sent';
      case 'エラー': return 'status-error';
      default: return 'status-pending';
    }
  }

  // 店舗選択肢を設定
  function populateStoreSelect() {
    const storeSelect = container.querySelector('#store-select');
    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';

    stores.forEach(store => {
      if (store.有効フラグ) {
        storeSelect.innerHTML += `<option value="${store.id}">${store.店舗名}</option>`;
      }
    });
  }

  // 選択した店舗の発注データを読み込み
  async function loadOrdersForStore(storeId) {
    if (!storeId) {
      currentOrders = [];
      renderOrderRows(currentOrders);
      return;
    }

    try {
      const allOrders = await window.aivicApi.list(ORDER_TABLE);
      if (allOrders) {
        // 選択した店舗の当日発注データをフィルタリング
        const today = new Date().toDateString();
        currentOrders = allOrders.filter(order => 
          order.店舗ID === storeId && 
          new Date(order.発注日).toDateString() === today
        );
        renderOrderRows(currentOrders);
      }
    } catch (error) {
      showError('発注データの読み込みに失敗しました');
    }
  }

  // 合計金額を更新
  function updateTotalAmount() {
    const checkboxes = container.querySelectorAll('.individual-checkbox:checked:not([disabled])');
    let total = 0;

    checkboxes.forEach(checkbox => {
      const orderId = checkbox.dataset.id;
      const order = currentOrders.find(o => o.id === orderId);
      if (order) {
        total += order.発注金額 || 0;
      }
    });

    container.querySelector('#total-amount').textContent = `¥${total.toLocaleString()}`;
  }

  // 全選択チェックボックスの処理
  function handleSelectAll() {
    const selectAllCheckbox = container.querySelector('#select-all');
    const individualCheckboxes = container.querySelectorAll('.individual-checkbox:not([disabled])');

    individualCheckboxes.forEach(checkbox => {
      checkbox.checked = selectAllCheckbox.checked;
    });

    updateTotalAmount();
  }

  // 個別チェックボックスの処理
  function handleIndividualCheckbox() {
    const selectAllCheckbox = container.querySelector('#select-all');
    const individualCheckboxes = container.querySelectorAll('.individual-checkbox:not([disabled])');
    const checkedCheckboxes = container.querySelectorAll('.individual-checkbox:checked:not([disabled])');

    selectAllCheckbox.checked = individualCheckboxes.length > 0 && individualCheckboxes.length === checkedCheckboxes.length;
    updateTotalAmount();
  }

  // 発注送信処理
  async function sendSelectedOrders() {
    const checkedCheckboxes = container.querySelectorAll('.individual-checkbox:checked:not([disabled])');

    if (checkedCheckboxes.length === 0) {
      showError('発注する商品を選択してください');
      return;
    }

    if (!confirm(`${checkedCheckboxes.length}件の発注を送信しますか？`)) {
      return;
    }

    let successCount = 0;
    let errorCount = 0;

    for (const checkbox of checkedCheckboxes) {
      const orderId = checkbox.dataset.id;
      const order = currentOrders.find(o => o.id === orderId);

      if (order && order.発注ステータス !== '送信済み') {
        try {
          // 発注ステータスを送信済みに更新
          await window.aivicApi.update(ORDER_TABLE, orderId, {
            発注ステータス: '送信済み',
            更新日時: new Date().toISOString(),
            更新者ID: 'current-user' // 実際の実装では現在のユーザーIDを使用
          });
          successCount++;
        } catch (error) {
          // エラーステータスに更新
          try {
            await window.aivicApi.update(ORDER_TABLE, orderId, {
              発注ステータス: 'エラー',
              更新日時: new Date().toISOString(),
              更新者ID: 'current-user'
            });
          } catch (updateError) {
            console.error('ステータス更新エラー:', updateError);
          }
          errorCount++;
        }
      }
    }

    // 画面を再読み込み
    const storeSelect = container.querySelector('#store-select');
    await loadOrdersForStore(storeSelect.value);

    // 結果メッセージを表示
    if (successCount > 0) {
      showSuccess(`${successCount}件の発注を正常に送信しました`);
    }
    if (errorCount > 0) {
      showError(`${errorCount}件の発注送信でエラーが発生しました`);
    }
  }

  // CSVエクスポート処理
  async function exportToCSV() {
    if (currentOrders.length === 0) {
      showError('エクスポートするデータがありません');
      return;
    }

    const headers = ['商品コード', '商品名', '予測需要数量', '発注数量', '仕入先名', '発注金額', '送信ステータス'];
    const csvData = [headers];

    currentOrders.forEach(order => {
      const product = products.find(p => p.id === order.商品ID) || {};
      csvData.push([
        product.商品コード || '',
        product.商品名 || '',
        order.予測数量 || 0,
        order.発注数量 || 0,
        order.仕入先名 || '',
        order.発注金額 || 0,
        order.発注ステータス || '送信待ち'
      ]);
    });

    const csvContent = '\uFEFF' + csvData.map(row => 
      row.map(field => `"${String(field).replace(/"/g, '""')}"`).join(',')
    ).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `発注送信データ_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    const successDiv = container.querySelector('#success-message');

    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    successDiv.classList.add('hidden');

    setTimeout(() => {
      errorDiv.classList.add('hidden');
    }, 5000);
  }

  // 成功メッセージ表示
  function showSuccess(message) {
    const successDiv = container.querySelector('#success-message');
    const errorDiv = container.querySelector('#error-message');

    successDiv.textContent = message;
    successDiv.classList.remove('hidden');
    errorDiv.classList.add('hidden');

    setTimeout(() => {
      successDiv.classList.add('hidden');
    }, 5000);
  }

  // 初期データ読み込み
  async function initializeData() {
    try {
      // 店舗マスタを読み込み
      const storeData = await window.aivicApi.list(STORE_TABLE);
      if (storeData) {
        stores = storeData;
        populateStoreSelect();
      }

      // 商品マスタを読み込み
      const productData = await window.aivicApi.list(PRODUCT_TABLE);
      if (productData) {
        products = productData;
      }

      // 初期表示（店舗未選択）
      renderOrderRows([]);

    } catch (error) {
      showError('初期データの読み込みに失敗しました');
    }
  }

  // イベントリスナー設定

  // 店舗選択変更
  container.querySelector('#store-select').addEventListener('change', (e) => {
    loadOrdersForStore(e.target.value);
  });

  // 全選択チェックボックス
  container.querySelector('#select-all').addEventListener('change', handleSelectAll);

  // 発注送信ボタン
  container.querySelector('#btn-send-orders').addEventListener('click', sendSelectedOrders);

  // CSVエクスポートボタン
  container.querySelector('#btn-export-csv').addEventListener('click', exportToCSV);

  // イベントデリゲーション（個別チェックボックス）
  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('individual-checkbox')) {
      handleIndividualCheckbox();
    }
  });

  // 初期化実行
  initializeData();
}
